def ca(P,rule,axis,wrap):
 b=(P==7).astype(int); Q=np.zeros_like(b)
 for r in range(5):
  for c in range(5):
   vals=[]
   for d in [-1,0,1]:
    rr=r+d if axis==0 else r;cc=c+d if axis==1 else c
    if wrap: vals.append(b[rr%5,cc%5])
    else:vals.append(b[rr,cc] if 0<=rr<5 and 0<=cc<5 else 0)
   idx=vals[0]*4+vals[1]*2+vals[2]
   Q[r,c]=(rule>>idx)&1
 return Q
for axis in [0,1]:
 for wrap in [0,1]:
  good=[rule for rule in range(256) if np.array_equal(ca(Y,rule,axis,wrap),A==7) and np.array_equal(ca(Yd,rule,axis,wrap),Ad==7)]
